const day_share=frac(i,'day_share',dflt(d,'planner_day_share'));const kw=pos(i,'sanctioned_kw',dflt(d,'default_sanctioned_kw'));const tou=kw>=dflt(d,'tou_threshold_kw');const peak_share=tou?num(i,'peak_share',{def:Math.min(dflt(d,'tou_peak_share'),1-day_share),min:0,max:1-day_share}):0;Object.assign(out,{sanctioned_kw:kw,tou,peak_share,tou_estimate:tou&&!has(i,'peak_share')});const bill={sanctioned_kw:kw,protected:false};const full_before=wholeBill(out,d,monthly_units,0);const before=tou?{energy_rs:full_before.energy_rs,rate:full_before.energy_rs/monthly_units||d.tariff.tou.offpeak}:bill_energy.raw({...bill,units:monthly_units},d);const above=out.installed_kw>kw+1e-9;const nb_panels=above?Math.floor((kw*1000)/out.panel_w+1e-9):out.panels;const nb_kw=(nb_panels*out.panel_w)/1000;const nb_solar_kwh=nb_kw*out.city_yield*days;const self_used=Math.min(nb_solar_kwh,monthly_units*day_share);const export_units=nb_solar_kwh-self_used;const import_units=monthly_units-self_used;const nb=net_billing.raw({...bill,import_units,export_units,peak_units:Math.min(monthly_units*peak_share,import_units),buyback_rs:has(i,'buyback_rs')?i.buyback_rs:undefined},d);const T=d.tariff.tou;Object.assign(out,{net_billing_panels:nb_panels,net_billing_kw:nb_kw,net_billing_solar_kwh:nb_solar_kwh,net_billing_inverter_kw:Math.max(out.inverter_kw_load,nb_kw/out.dc_ac_ratio_max),day_share,self_used_units:self_used,export_units,import_units,buyback_rs:nb.buyback_rs,bill_before_rs:before.energy_rs,rate_before:before.rate,bill_after_rs:nb.net_energy_rs,carry_forward_rs:nb.carry_forward_rs,saving_rs:Math.max(0,before.energy_rs-nb.net_energy_rs),solar_above_sanctioned:above,tariff_text:tou?`ToU tariff (${fmt(peak_share,'pct')} of your use in the peak hours at ${fmt(T.peak,'rs2')}, the rest at ${fmt(T.offpeak,'rs2')}; solar replaces off-peak units only; fixed charge on half the sanctioned load, more if your MDI is higher)`:'slab tariff',});const full_import=wholeBill(out,d,monthly_units,self_used);const full