function wholeBill(p,d,use,self){const b={sanctioned_kw:p.sanctioned_kw,protected:false};const peak=Math.max(0,Math.min(use*p.peak_share,use-self));return p.tou?bill_tou.raw({...b,peak_units:peak,offpeak_units:Math.max(0,use-self-peak)},d):bill_total.raw({...b,units:Math.max(0,use-self)},d);}
